import numpy as np, pandas as pd
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares
g=9.81
a=df[(df.air_density>0)].reset_index(drop=True)
sh={'sphere':0,'cylinder':1,'cube':2}
def sim(r,cd):
    k=0.5*r.air_density*cd*np.pi*r.radius**2/r.mass
    th=np.radians(r.angle)
    def f(t,y):
        vx,vy=y[2],y[3];v=np.hypot(vx,vy)
        return [vx,vy,-k*v*vx,-g-k*v*vy]
    ev=lambda t,y:y[1]; ev.terminal=True; ev.direction=-1
    s=solve_ivp(f,[0,100],[0,r.height,r.speed*np.cos(th),r.speed*np.sin(th)],events=ev,rtol=1e-8,atol=1e-8)
    y=s.y_events[0][0]; return s.t_events[0][0],y[0],np.hypot(y[2],y[3])
def res(p,model):
    out=[]
    for _,r in a.iterrows():
        cd=p[sh[r['shape']]]
        if model>=1: cd*=(1+p[3]*(r.reflectance-0.5))
        if model>=2: cd*=(1+p[4]*(r.temperature-30)/50)
        t,dd,v=sim(r,cd)
        out.append((r.flight_time-t)/0.01); out.append((r.impact_speed-v)/(0.01*v))
        if r.speed>0 and np.cos(np.radians(r.angle))>0: out.append((r.distance-dd)/(0.01*dd))
    return np.array(out)
for m,p0 in [(0,[0.47,0.82,1.35]),(1,[0.47,0.82,1.35,0]),(2,[0.47,0.82,1.35,0,0])]:
    f=least_squares(res,p0,args=(m,))
    J=f.jac; cov=np.linalg.inv(J.T@J)*(2*f.cost/(len(f.fun)-len(p0)))
    print(m,np.round(f.x,4),np.round(np.sqrt(np.diag(cov)),4),'chi2/N',round(2*f.cost/len(f.fun),3))

